using System; using Microsoft.UI.Xaml; using Windows.Services.Store; using WinRT.Interop; using System.IO; using Newtonsoft.Json.Linq; using System.Threading.Tasks;  namespace Playgama.Bridge.Wrappers.MicrosoftStore {     public sealed partial class MainWindow : Window     {         private readonly StoreContext _store;         private readonly nint _hwnd;          private const string AppSettingsFileName = "appsettings.json";          private static async Task<string> GetClientIdAsync()         {             var path = Path.Combine(AppContext.BaseDirectory, AppSettingsFileName);              if (!File.Exists(path))                 return "";              var text = await File.ReadAllTextAsync(path).ConfigureAwait(false);             if (string.IsNullOrWhiteSpace(text))                 return "";              var json = JObject.Parse(text);             return (string?)json["clientId"] ?? "";         }          public MainWindow()         {             InitializeComponent();              _hwnd = WindowNative.GetWindowHandle(this);              SetWindowIcon("Assets\\favicon.ico");              ExtendsContentIntoTitleBar = true;             SetTitleBar(AppTitleBar);              _store = StoreContext.GetDefault();             InitializeWithWindow.Initialize(_store, _hwnd);              _ = InitializeAsync();         }     } } 